// Main-owned isolated local commit, never a push of canonical/native ancestry.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {execFileSync} from 'node:child_process';
import {hash,json} from './seal-simple-website-successor.mjs';
const root='F:/VisibleMedicine/recovery/checkpoints/20261024-native-verified-source';assert(!fs.existsSync(root));
const oldFile='F:/VisibleMedicine/recovery/checkpoints/20261024-native-metadata-and-active-tests/NATIVE_SOURCE_POST_METADATA.json',oldHash='cdf1e48cb8e5cecec02e6db51362053e266839b9c9caef08d3c8daa819e250ef';assert.equal(hash(oldFile),oldHash);const source=json(oldFile),atlas=source.atlas;
const memory=JSON.parse(execFileSync('powershell',['-NoProfile','-NonInteractive','-Command','Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory | Select-Object AvailableMBytes,PercentCommittedBytesInUse | ConvertTo-Json -Compress'],{encoding:'utf8',windowsHide:true}));assert(memory.AvailableMBytes>=2048&&memory.PercentCommittedBytesInUse<=90);
const git=(args,input)=>execFileSync('git',['-C',atlas,...args],{encoding:input?'buffer':'utf8',input,windowsHide:true,maxBuffer:4*1024*1024,env:{...process.env,GIT_TERMINAL_PROMPT:'0'}});
const checks=[atlas+'/../checks/right-gastric-eus-attempt-1/TERMINAL.json',...['freshness','regional'].map(mode=>atlas+'/../checks/generated-gates-v1/'+mode+'-attempt-1/TERMINAL.json'),atlas+'/../checks/generated-gates-v2/strict-attempt-1/TERMINAL.json'];for(const file of checks)assert.equal(json(file).passing,true,file);
assert.equal(json(checks[0]).counts.pass,13);assert.equal(json(checks[2]).results[0].counts.pass,27);assert.equal(json(checks[3]).fullNativeStrict,true);
assert.equal(git(['rev-parse','HEAD']).trim(),source.head);assert.equal(git(['rev-parse','HEAD^{tree}']).trim(),source.tree);assert.equal(git(['diff','--cached','--name-only']).trim(),'');
const status=()=>git(['-c','core.quotepath=false','status','--porcelain=v1','-z','--untracked-files=all']).split('\0').filter(Boolean).map(s=>({path:s.slice(3),code:s.slice(0,2)})).sort((a,b)=>a.path.localeCompare(b.path));assert.deepEqual(status(),source.dirty);assert.equal(source.dirty.length,12);for(const r of source.dirty){assert([' M','??'].includes(r.code));assert(!r.path.includes('..')&&!r.path.startsWith('.local/'));}
for(const r of source.sourceRows){assert.equal(hash(atlas+'/'+r.path),r.sha256);assert.equal(fs.statSync(atlas+'/'+r.path).size,r.bytes);}
fs.mkdirSync(root);const save=(name,v)=>fs.writeFileSync(root+'/'+name,JSON.stringify(v,null,2)+'\n',{flag:'wx'});
save('STARTED.json',{at:new Date().toISOString(),memory,sourceFile:oldFile,sourceSha256:oldHash,parentHead:source.head,parentTree:source.tree,paths:source.dirty.map(r=>r.path),checks:checks.map(path=>({path,sha256:hash(path)})),scope:'Isolated native source only, no public deployment, remote native push or owner-preview change'});
try{
 git(['add','--',...source.dirty.map(r=>r.path)]);assert.deepEqual(git(['diff','--cached','--name-only','-z']).split('\0').filter(Boolean).sort(),source.dirty.map(r=>r.path).sort());
 const output=git(['-c','user.name=Visible Medicine source checkpoint','-c','user.email=source-checkpoint@users.noreply.github.com','commit','-m','Atlas: source-bound right gastric EUS draft and compact review headings']);fs.writeFileSync(root+'/commit-output.log',output,{flag:'wx'});
 const head=git(['rev-parse','HEAD']).trim(),tree=git(['rev-parse','HEAD^{tree}']).trim();assert.notEqual(head,source.head);assert.equal(git(['rev-parse','HEAD^']).trim(),source.head);assert.deepEqual(status(),[]);
 for(const r of source.sourceRows){assert.equal(hash(atlas+'/'+r.path),r.sha256);assert.equal(fs.statSync(atlas+'/'+r.path).size,r.bytes);}
 for(const r of source.dirty){const b=fs.readFileSync(atlas+'/'+r.path),blob=git(['hash-object','--no-filters','--stdin'],b).toString().trim();assert.equal(git(['rev-parse',head+':'+r.path]).trim(),blob,'Exact working bytes committed: '+r.path);}
 const result={...source,schema:'vm-native-verified-committed-source/1',at:new Date().toISOString(),head,tree,parentHead:source.head,parentTree:source.tree,previousSource:{path:oldFile,sha256:oldHash},dirty:[],committedPaths:source.dirty.map(r=>r.path),allSourceBytesUnchangedByCommit:true,newSourceFilesByteExactInGit:true,checks:checks.map(path=>({path,sha256:hash(path)})),buildRun:false,installed:false,previewChanged:false,remoteNativeAncestryPushed:false,clinicalApproval:false};save('SOURCE_COMMITTED.json',result);save('TERMINAL.json',{at:new Date().toISOString(),status:'isolated-local-source-commit-verified',head,tree,sourceFile:root+'/SOURCE_COMMITTED.json',sourceSha256:hash(root+'/SOURCE_COMMITTED.json'),paths:12,workingTreeClean:true,privateDataUploaded:false,remoteNativeAncestryPushed:false,installed:false,previewChanged:false});console.log(JSON.stringify({head,tree,sourceFile:root+'/SOURCE_COMMITTED.json',sourceSha256:hash(root+'/SOURCE_COMMITTED.json'),paths:12,workingTreeClean:true}));
}catch(error){save('FAILURE.json',{at:new Date().toISOString(),message:error.message,stack:error.stack,commitOutcomeMustBeInspectedBeforeAnyRetry:true});throw error;}
